## 💻 IMPLEMENTACIÓN BUILD.AI MAX (Código de Producción Real)

### 1. `schema.sql` — Base de Datos con RLS + Zero-Knowledge

```sql
-- Enable extensions
create extension if not exists "uuid-ossp";
create extension if not exists "pgcrypto";

-- users: anonimato por defecto, seudónimo opcional, consentimiento granular
create table users (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz default now(),
  pseudonym text unique, -- opcional, para comunidad, encriptado si se proporciona
  preferences jsonb default '{"lang":"es","theme":"dark","agents":["queer","neuro","safety"],"accessibility":{}}',
  mood_history jsonb default '[]', -- [{timestamp, mood, trigger, duration}]
  consent jsonb default '{"research":false,"community":false,"analytics":false,"ecosystem":false}',
  last_active timestamptz default now(),
  -- Zero-knowledge: datos sensibles encriptados cliente-lado
  encrypted_profile_data bytea, -- encriptado con clave derivada de contraseña del usuario
  key_version int default 1 -- para rotación de claves
);

-- assessments: tests con lógica en edge functions, resultados solo para usuario
create table assessments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references users(id) on delete cascade,
  type text not null check (type in ('radar', 'clusterb', 'triads', 'neuro', 'consumption', 'sensory')),
  version text not null default '6.0', -- versión del test para reproducibilidad
  answers jsonb not null, -- respuestas encriptadas si contienen datos sensibles
  score numeric,
  insights jsonb, -- recomendaciones personalizadas generadas por AI agent
  risk_level text check (risk_level in ('low','moderate','high','crisis')),
  resources_suggested text[], -- IDs de recursos recomendados
  created_at timestamptz default now(),
  expires_at timestamptz, -- para tests de crisis: auto-borrado después de 24h
  -- RLS: solo el usuario puede ver sus propios assessments
  constraint user_owns_assessment check (user_id is not null)
);

-- stories: relatos anónimos con moderación comunitaria + crisis detection
create table stories (
  id uuid primary key default gen_random_uuid(),
  author_pseudonym text, -- opcional, puede ser "Anónimo", encriptado si se proporciona
  title text not null,
  content text not null,
  tags text[] default '{}', -- ['trans', 'tdah', 'bpd', 'chemsex', 'sanación', 'crisis']
  mood_context text check (mood_context in ('fiesta','bajada','dejar','cuidador','curioso','crisis')),
  identity_context jsonb default '{}', -- {queer:true, neurodivergent:true, etc.} para filtrado seguro
  upvotes int default 0,
  downvotes int default 0,
  flagged boolean default false,
  flag_reasons text[],
  moderator_notes text,
  crisis_keywords_detected text[], -- keywords que activaron revisión de seguridad
  created_at timestamptz default now(),
  published boolean default false, -- requiere aprobación inicial + verificación de seguridad
  published_at timestamptz,
  -- RLS policies específicas para historias
  constraint content_length check (char_length(content) <= 5000)
);

-- resources: guías, centros, líneas de crisis, verificados por región
create table resources (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text,
  type text not null check (type in ('guide','center','hotline','app','research','community')),
  url text,
  phone text,
  email text,
  location jsonb, -- {city, country, coords:{lat,lng}, accessibility_notes}
  lgbtq_friendly boolean default true,
  neuro_affirming boolean default true,
  languages text[] default '["es","en"]',
  verified_by text, -- "Energy Control", "Trevor Project", "Colegio Psicólogos", etc.
  verification_date date,
  crisis_capable boolean default false, -- si puede atender emergencias 24/7
  cost text default 'free', -- 'free','sliding_scale','insurance','private'
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  -- Geospatial index para búsqueda por ubicación
  constraint valid_coords check (location->'coords' is null or (location->'coords'->>'lat' is not null and location->'coords'->>'lng' is not null))
);

-- agents_config: personalización de IA por usuario
create table agents_config (
  user_id uuid references users(id) primary key,
  active_agents jsonb default '["queerAffirm","neuroDivergent","crisisGuard"]',
  tone_preference text default 'pop' check (tone_preference in ('pop','clinical','poetic','street')),
  cultural_context text default 'es' check (cultural_context in ('es','latam','br','global')),
  crisis_keywords_custom jsonb default '[]', -- palabras adicionales que el usuario quiere que activen ayuda
  avoid_topics text[] default '{}', -- temas que el usuario prefiere evitar
  notification_preferences jsonb default '{"crisis":true,"community":false,"research":false}',
  updated_at timestamptz default now()
);

-- ecosystem_links: navegación contextual entre proyectos Belentani
create table ecosystem_links (
  id uuid primary key default gen_random_uuid(),
  source_project text not null check (source_project in ('mental-map','el-espejo-judas','dual-scars','tomaagua','refleja-tu-fuerza','eco-silencio')),
  target_project text not null,
  context_trigger jsonb not null, -- {keywords:[], mood:[], identity:[], risk_level:[]}
  deep_link text not null,
  confidence_threshold numeric default 0.7,
  display_text jsonb not null, -- {es:"", en:"", ca:"", pt:""}
  created_at timestamptz default now(),
  active boolean default true
);

-- research_opt_in: datos anonimizados para investigación colaborativa
create table research_opt_in (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references users(id) on delete cascade unique,
  consent_given_at timestamptz default now(),
  data_types jsonb default '[]', -- ['mood_patterns','resource_usage','test_answers_anonymized']
  research_projects jsonb default '[]', -- IDs de proyectos de investigación aprobados
  withdrawal_requested_at timestamptz,
  data_deleted_at timestamptz,
  constraint consent_active check (withdrawal_requested_at is null or data_deleted_at is not null)
);

-- crisis_logs: métricas anonimizadas de intervenciones (sin datos personales)
create table crisis_logs (
  id uuid primary key default gen_random_uuid(),
  timestamp timestamptz default now(),
  trigger_type text, -- 'keyword','pattern','user_report','agent_detection'
  severity text check (severity in ('low','moderate','high','critical')),
  intervention_type text, -- 'show_resources','offer_chat','escalate_human'
  outcome text, -- 'user_engaged','user_declined','escalated','resolved'
  region text, -- solo país/región, nunca ubicación precisa
  agent_version text, -- versión del agente de crisis para auditoría
  -- Zero-knowledge: sin user_id, sin IP, sin identificadores
  constraint anonymized check (user_id is null and ip_address is null)
);

-- Índices para rendimiento
create index idx_assessments_user on assessments(user_id, created_at desc);
create index idx_stories_published on stories(published, created_at desc) where published = true;
create index idx_resources_location on resources using gin(location);
create index idx_crisis_logs_timestamp on crisis_logs(timestamp desc);

-- Row Level Security (RLS) policies
alter table users enable row level security;
create policy "Users can read own data" on users for select using (auth.uid()::uuid = id);
create policy "Users can update own data" on users for update using (auth.uid()::uuid = id);
create policy "Users can delete own account" on users for delete using (auth.uid()::uuid = id);

alter table assessments enable row level security;
create policy "Users own their assessments" on assessments for all using (auth.uid()::uuid = user_id);
create policy "Assessments auto-expire" on assessments for delete using (expires_at is not null and expires_at < now());

alter table stories enable row level security;
create policy "Anyone can read published stories" on stories for select using (published = true);
create policy "Users can create stories" on stories for insert with check (auth.uid() is not null and char_length(content) > 10);
create policy "Users can update own unpublished stories" on stories for update using (auth.uid() is not null and published = false);
create policy "Moderators can manage stories" on stories for all using (auth.role() = 'moderator');

alter table resources enable row level security;
create policy "Anyone can read resources" on resources for select using (true);
create policy "Only verified admins can modify resources" on resources for all using (auth.role() = 'admin' and auth.email() like '%@belentani.org');

alter table agents_config enable row level security;
create policy "Users own their agent config" on agents_config for all using (auth.uid()::uuid = user_id);

alter table ecosystem_links enable row level security;
create policy "Anyone can read active ecosystem links" on ecosystem_links for select using (active = true);

alter table research_opt_in enable row level security;
create policy "Users own their research consent" on research_opt_in for all using (auth.uid()::uuid = user_id);

-- Functions for zero-knowledge encryption helpers
create or replace function generate_user_key(user_password text, salt text)
returns bytea as $$
declare
  key bytea;
begin
  -- Derivar clave usando PBKDF2 (en producción, usar libsodium via edge function)
  key := digest(user_password || salt, 'sha256');
  return key;
end;
$$ language plpgsql security definer;

-- Trigger para actualizar updated_at automáticamente
create or replace function update_updated_at_column()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

create trigger update_resources_updated_at
  before update on resources
  for each row
  execute function update_updated_at_column();

create trigger update_agents_config_updated_at
  before update on agents_config
  for each row
  execute function update_updated_at_column();
