// BuildAI Edge Function: CEO Orchestrator v∞
// Enruta cada interacción al agente más adecuado según contexto, identidad, riesgo y preferencias

import { createClient } from '@supabase/supabase-js'
import { 
  detectCrisis, 
  detectIdentity, 
  detectNeurotype, 
  detectCulturalContext,
  calculateRiskScore 
} from './utils/detection'
import { logCrisisEvent, anonymizeUserData } from './utils/privacy'
import { routeToAgent } from './agents/router'

// Configuración de seguridad ética
const ETHICAL_GUARDRAILS = {
  maxResponseTime: 3000, // 3 segundos máximo para respuesta de crisis
  requireHumanEscalation: ['suicidio', 'autolesión', 'homicidio', 'abuso sexual'],
  anonymizeBeforeLogging: true,
  consentRequiredForStorage: true,
  neverStore: ['passwords', 'exact_location', 'full_name', 'government_id']
}

export default async function handler(req: Request, context: any) {
  try {
    const { message, userId, sessionId, context: userContext } = await req.json()

    // 1. Validación ética inicial: ¿tiene consentimiento para procesamiento?
    if (userContext.requiresConsent && !userContext.hasConsent) {
      return new Response(JSON.stringify({
        response: "Antes de continuar, necesito tu consentimiento para procesar esta conversación. ¿Aceptas que use esta información solo para ayudarte ahora, sin guardarla permanentemente?",
        actions: [{ type: 'requestConsent', options: ['yes_anonymous', 'yes_with_account', 'no_exit'] }]
      }), { headers: { 'Content-Type': 'application/json' } })
    }

    // 2. Análisis de contexto en tiempo real (todo en memoria, sin persistencia)
    const crisis = detectCrisis(message, userContext.lang)
    const identity = detectIdentity(message, userContext.lang)
    const neurotype = detectNeurotype(message, userContext.lang)
    const cultural = detectCulturalContext(message, userContext.lang)
    const riskScore = calculateRiskScore({ crisis, identity, neurotype, message })

    // 3. Logging anonimizado de métricas (solo para mejorar el sistema, nunca para tracking)
    if (ETHICAL_GUARDRAILS.anonymizeBeforeLogging) {
      await logCrisisEvent({
        trigger_type: crisis.detected ? 'keyword' : 'pattern',
        severity: crisis.severity,
        region: userContext.country || 'unknown',
        agent_version: 'ceo-orchestrator-v1.0',
        // Zero-knowledge: sin user_id, sin IP, sin identificadores
      }).catch(err => console.error('Anonymous logging failed:', err))
    }

    // 4. Intervención inmediata si es crisis de alto riesgo
    if (crisis.severity === 'critical' || crisis.detected) {
      const intervention = await handleCrisisIntervention({
        crisis,
        identity,
        cultural,
        userContext
      })

      // Escalación a humano si es necesario
      if (intervention.requiresHuman) {
        await escalateToHuman({
          severity: crisis.severity,
          region: userContext.country,
          language: userContext.lang,
          // Zero-knowledge: sin datos personales, solo contexto de ayuda
        })
      }

      return new Response(JSON.stringify(intervention), {
        headers: { 'Content-Type': 'application/json' }
      })
    }

    // 5. Selección dinámica de agente principal según contexto
    let primaryAgent = 'educator' // default fallback

    if (identity.queer && userContext.activeAgents?.includes('queerAffirm')) {
      primaryAgent = 'queerAffirm'
    } else if (neurotype.detected && userContext.activeAgents?.includes('neuroDivergent')) {
      primaryAgent = 'neuroDivergent'
    } else if (message.toLowerCase().includes('test') || message.toLowerCase().includes('evaluar')) {
      primaryAgent = 'playful'
    } else if (cultural.requiresAdaptation && userContext.activeAgents?.includes('culturalAdapter')) {
      primaryAgent = 'culturalAdapter'
    }

    // 6. Enrutamiento al agente especializado con contexto enriquecido
    const agentPayload = {
      message,
      userId,
      sessionId,
      context: {
        ...userContext,
        crisis,
        identity,
        neurotype,
        cultural,
        riskScore,
        timestamp: new Date().toISOString()
      },
      ethicalConstraints: {
        neverDiagnose: true,
        alwaysValidate: true,
        offerResources: true,
        respectAutonomy: true
      }
    }

    const agentResponse = await routeToAgent(primaryAgent, agentPayload)

    // 7. Post-procesamiento: adaptar tono, añadir recursos, verificar seguridad
    const finalResponse = {
      ...agentResponse,
      meta {
        agent: primaryAgent,
        confidence: agentResponse.confidence || 0.85,
        resources: await suggestResources({ identity, neurotype, cultural, riskScore, lang: userContext.lang }),
        followUp: generateFollowUpQuestion(primaryAgent, message, identity),
        accessibility: {
          simplified: userContext.accessibility?.simplifyContent || false,
          largeText: userContext.accessibility?.largeText || false,
          reducedMotion: userContext.accessibility?.reducedMotion || false
        }
      },
      safety: {
        crisisDetected: crisis.detected,
        riskLevel: riskScore.level,
        requiresHumanReview: riskScore.level === 'high',
        logged: ETHICAL_GUARDRAILS.anonymizeBeforeLogging,
        consentStatus: userContext.hasConsent ? 'given' : 'pending'
      },
      ecosystem: {
        suggestedNextSteps: await suggestEcosystemNavigation({
          currentProject: 'mental-map',
          userContext: { identity, neurotype, mood: userContext.mood }
        })
      }
    }

    return new Response(JSON.stringify(finalResponse), {
      headers: { 
        'Content-Type': 'application/json',
        'X-Response-Time': `${Date.now() - (context?.startTime || Date.now())}ms`,
        'X-Ethical-Compliance': 'v1.0'
      }
    })

  } catch (error) {
    console.error('CEO Orchestrator error:', error)

    // Fallback ético: nunca dejar al usuario sin respuesta
    return new Response(JSON.stringify({
      response: "Lo siento, tuve un problema técnico. Pero estoy aquí para ti. ¿Puedes contarme más sobre lo que necesitas? Mientras tanto, si estás en crisis, estos números pueden ayudarte ahora mismo: [números de crisis según región].",
      actions: [
        { type: 'showEmergencyNumbers', regions: ['es', 'latam', 'br', 'global'] },
        { type: 'retryWithSimplerRequest', message: "Intenta preguntar de otra forma o usa palabras más simples" }
      ],
      safety: {
        fallback: true,
        humanEscalationAvailable: true
      }
    }), { 
      headers: { 'Content-Type': 'application/json' },
      status: 200 // Siempre 200 para no activar alarmas en frontend
    })
  }
}

// Función de intervención de crisis con protocolos éticos
async function handleCrisisIntervention({ crisis, identity, cultural, userContext }) {
  const lang = userContext.lang || 'es'
  const region = userContext.country || 'es'

  // Mensajes de intervención validados por profesionales de salud mental LGBTQ+
  const crisisMessages = {
    es: {
      critical: "Escucho que estás pasando por un momento muy difícil. No estás solx. Tu vida importa. ¿Puedo conectarte ahora mismo con ayuda profesional que entiende tu realidad LGBTQ+ y neurodivergente?",
      high: "Veo que esto es muy intenso para ti ahora. Es válido sentirse así. ¿Te gustaría que te muestre recursos de apoyo que han ayudado a otras personas en situaciones similares?",
      moderate: "Entiendo que esto te está afectando mucho. No tienes que manejar esto solx. ¿Quieres explorar algunas estrategias de grounding o hablar con alguien que pueda ayudarte?"
    },
    en: {
      critical: "I hear you're going through a really tough moment. You're not alone. Your life matters. Can I connect you right now with professional help that understands your LGBTQ+ and neurodivergent reality?",
      high: "I see this is very intense for you right now. It's valid to feel this way. Would you like me to show you support resources that have helped others in similar situations?",
      moderate: "I understand this is affecting you deeply. You don't have to handle this alone. Would you like to explore some grounding strategies or talk to someone who can help?"
    }
    // ... más idiomas
  }

  // Recursos de crisis verificados por región e identidad
  const crisisResources = await getCrisisResources({ region, identity, lang })

  return {
    response: crisisMessages[lang]?.[crisis.severity] || crisisMessages.es[crisis.severity],
    actions: [
      { 
        type: 'showCrisisResources', 
        resources: crisisResources,
        displayMode: userContext.accessibility?.simplifyContent ? 'simplified' : 'full'
      },
      { 
        type: 'offerHumanChat', 
        available: crisis.severity !== 'low',
        languages: ['es', 'en', 'pt'],
        queerAffirming: true,
        neuroAffirming: true
      },
      { 
        type: 'groundingExercise', 
        exercise: '5-4-3-2-1',
        duration: 90, // segundos
        accessibility: { voiceGuided: true, textOnly: true, haptic: true }
      }
    ],
    requiresHuman: crisis.severity === 'critical' || crisis.keywords?.some(k => ETHICAL_GUARDRAILS.requireHumanEscalation.includes(k)),
    autoEscalate: crisis.severity === 'critical',
    followUpIn: crisis.severity === 'moderate' ? 3600 : null // seguir en 1 hora si es moderado
  }
}

// Sugerencia de recursos basada en evidencia y contexto
async function suggestResources({ identity, neurotype, cultural, riskScore, lang }) {
  const supabase = createClient(
    process.env.SUPABASE_URL!,
    process.env.SUPABASE_ANON_KEY!
  )

  // Construir query segura con filtros de identidad y neurodivergencia
  let query = supabase
    .from('resources')
    .select('id, title, description, type, url, phone, location, lgbtq_friendly, neuro_affirming, languages')
    .eq('published', true)
    .in('languages', [lang, 'en']) // fallback a inglés
    .order('verification_date', { ascending: false })
    .limit(5)

  // Filtros afirmativos si el contexto lo indica
  if (identity.queer) {
    query = query.eq('lgbtq_friendly', true)
  }
  if (neurotype.detected) {
    query = query.eq('neuro_affirming', true)
  }
  if (cultural.region) {
    query = query.contains('location', { country: cultural.region })
  }

  const {  resources, error } = await query

  if (error) {
    console.error('Resource suggestion error:', error)
    return [] // Fallback seguro: sin recursos en lugar de recursos incorrectos
  }

  // Priorizar por relevancia de contexto
  return resources
    .map(r => ({
      ...r,
      relevanceScore: calculateResourceRelevance(r, { identity, neurotype, cultural, riskScore })
    }))
    .sort((a, b) => b.relevanceScore - a.relevanceScore)
    .slice(0, 3) // Top 3 más relevantes
}

// Navegación contextual en el ecosistema Belentani
async function suggestEcosystemNavigation({ currentProject, userContext }) {
  const supabase = createClient(
    process.env.SUPABASE_URL!,
    process.env.SUPABASE_ANON_KEY!
  )

  // Buscar enlaces del ecosistema que coincidan con el contexto del usuario
  const {  links, error } = await supabase
    .from('ecosystem_links')
    .select('target_project, deep_link, display_text, confidence_threshold')
    .eq('source_project', currentProject)
    .eq('active', true)
    .contains('context_trigger', { 
      mood: userContext.mood ? [userContext.mood] : [],
      identity: userContext.identity?.queer ? ['queer'] : [],
      neurodivergent: userContext.neurotype?.detected ? [true] : []
    })
    .limit(2)

  if (error || !links?.length) {
    return [] // Sin sugerencias si no hay coincidencias seguras
  }

  // Filtrar por umbral de confianza y adaptar texto al idioma
  return links
    .filter(link => link.confidence_threshold <= 0.8) // Solo sugerencias de alta confianza
    .map(link => ({
      project: link.target_project,
      url: link.deep_link,
      text: link.display_text[userContext.lang] || link.display_text.es,
      reason: generateNavigationReason(link.target_project, userContext)
    }))
}

function generateNavigationReason(targetProject: string, userContext: any): string {
  const reasons: Record<string, Record<string, string>> = {
    'el-espejo-judas': {
      es: "Si identificaste patrones de manipulación emocional, aquí puedes aprender a nombrarlos y protegerte",
      en: "If you identified emotional manipulation patterns, here you can learn to name them and protect yourself"
    },
    'dual-scars': {
      es: "Si necesitas documentar lo que vives para recuperar tu poder, este espacio te da herramientas seguras",
      en: "If you need to document what you're experiencing to reclaim your power, this space gives you safe tools"
    },
    'tomaagua': {
      es: "Si el consumo de sustancias es parte de tu realidad, aquí encontrarás reducción de daños sin juicios",
      en: "If substance use is part of your reality, here you'll find harm reduction without judgment"
    }
  }

  return reasons[targetProject]?.[userContext.lang] || reasons[targetProject]?.es || ""
}
