// BuildAI React Component: Radar Test v6.0 - Adaptativo, Científico, Ético
import { useState, useEffect, useCallback } from 'react'
import { invokeEdgeFunction } from '@buildai/sdk'
import { motion, AnimatePresence } from 'framer-motion'
import { useAccessibility } from '../hooks/useAccessibility'
import { useConsent } from '../hooks/useConsent'
import { CrisisBanner } from './shared/CrisisBanner'

interface RadarTestProps {
  userId?: string
  sessionId: string
  onComplete?: (results: RadarResults) => void
  context: {
    lang: string
    mood: string
    identity?: { queer?: boolean }
    neurotype?: { detected?: boolean }
    accessibility?: AccessibilityPreferences
  }
}

interface RadarResults {
  insights: {
    emotionalRegulation: 'low' | 'moderate' | 'high'
    sensorySensitivity: 'low' | 'moderate' | 'high'
    minorityStress: 'low' | 'moderate' | 'high'
    executiveFunction: 'low' | 'moderate' | 'high'
  }
  recommendations: ResourceRecommendation[]
  riskLevel: 'low' | 'moderate' | 'high' | 'crisis'
  personalizedMessage: string
}

interface ResourceRecommendation {
  id: string
  title: string
  type: 'guide' | 'center' | 'hotline' | 'community'
  relevance: number
  action: { type: 'view' | 'call' | 'chat' | 'save' }
}

export default function InteractiveRadar6({ userId, sessionId, onComplete, context }: RadarTestProps) {
  const [step, setStep] = useState(0)
  const [answers, setAnswers] = useState<Record<number, any>>({})
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<RadarResults | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [currentQuestion, setCurrentQuestion] = useState<AdaptiveQuestion | null>(null)

  const { profile: accessibilityProfile } = useAccessibility()
  const { hasConsent, requestConsent } = useConsent()

  // Total de pasos dinámico según respuestas anteriores (adaptativo)
  const [totalSteps, setTotalSteps] = useState(5)

  // Cargar pregunta inicial o adaptativa
  const loadQuestion = useCallback(async (prevAnswer?: any) => {
    if (loading) return

    setLoading(true)
    setError(null)

    try {
      const { question, nextSteps } = await invokeEdgeFunction('radar-adaptive-engine-v6', {
        sessionId,
        userId,
        step,
        prevAnswer,
        context: {
          lang: context.lang,
          mood: context.mood,
          identity: context.identity,
          neurotype: context.neurotype,
          accessibility: accessibilityProfile
        },
        ethicalConstraints: {
          neverDiagnose: true,
          alwaysValidate: true,
          consentRequired: !hasConsent
        }
      })

      setCurrentQuestion(question)

      // Si el motor adaptativo cambia el número total de pasos, actualizar
      if (nextSteps && nextSteps !== totalSteps) {
        setTotalSteps(nextSteps)
      }

      // Solicitar consentimiento si es necesario y no se ha dado
      if (!hasConsent && question.requiresConsent) {
        const consentGiven = await requestConsent({
          purpose: 'personalize-test-results',
          duration: 'this-session-only',
          dataTypes: ['answers', 'mood-context'],
          sharing: 'never-share-with-third-parties'
        })

        if (!consentGiven) {
          // Si no da consentimiento, continuar con modo anónimo limitado
          setCurrentQuestion(prev => prev ? { ...prev, anonymousMode: true } : null)
        }
      }

    } catch (err) {
      console.error('Error loading question:', err)
      setError('No pude cargar la pregunta. ¿Quieres intentarlo de nuevo o usar el modo simplificado?')

      // Fallback a pregunta estática si falla la adaptativa
      setCurrentQuestion(getFallbackQuestion(step, context.lang))
    } finally {
      setLoading(false)
    }
  }, [step, sessionId, userId, context, accessibilityProfile, hasConsent, requestConsent, loading, totalSteps])

  // Efecto para cargar pregunta al montar o cambiar de paso
  useEffect(() => {
    if (step < totalSteps && !currentQuestion) {
      loadQuestion(answers[step - 1])
    }
  }, [step, totalSteps, currentQuestion, loadQuestion, answers])

  // Manejar respuesta del usuario
  const handleAnswer = async (answer: any) => {
    // Guardar respuesta localmente primero (para recuperación si falla la red)
    setAnswers(prev => ({ ...prev, [step]: answer }))

    // Feedback visual inmediato
    const optionElements = document.querySelectorAll('.option-btn')
    optionElements.forEach(btn => {
      if (btn.getAttribute('data-value') === JSON.stringify(answer.value)) {
        btn.classList.add('selected')
        // Haptic feedback en móvil si está disponible
        if ('vibrate' in navigator) {
          navigator.vibrate(50)
        }
      }
    })

    // Si es la última pregunta, calcular resultado final
    if (step === totalSteps - 1) {
      await finalizeTest({ ...answers, [step]: answer })
    } else {
      // Cargar siguiente pregunta adaptativa
      setStep(prev => prev + 1)
      // La pregunta se cargará automáticamente por el useEffect
    }
  }

  // Finalizar test y obtener resultados
  const finalizeTest = async (finalAnswers: Record<number, any>) => {
    setLoading(true)

    try {
      const { insights, recommendations, riskLevel, personalizedMessage } = await invokeEdgeFunction('radar-finalize-v6', {
        sessionId,
        userId,
        answers: finalAnswers,
        context: {
          lang: context.lang,
          mood: context.mood,
          identity: context.identity,
          neurotype: context.neurotype,
          accessibility: accessibilityProfile
        },
        consent: {
          saveResults: hasConsent,
          anonymized: !hasConsent,
          research: false // por defecto, se puede cambiar en preferencias
        }
      })

      const results: RadarResults = {
        insights,
        recommendations,
        riskLevel,
        personalizedMessage
      }

      setResult(results)

      // Callback para el componente padre
      onComplete?.(results)

      // Guardar resultados solo si hay consentimiento explícito
      if (hasConsent && userId) {
        await invokeEdgeFunction('save-assessment-v6', {
          userId,
          type: 'radar-v6',
          answers: finalAnswers,
          results,
          anonymized: false
        }).catch(err => console.warn('Failed to save results:', err))
      }

    } catch (err) {
      console.error('Error finalizing test:', err)
      setError('No pude procesar tus respuestas. Pero tus respuestas están guardadas localmente. ¿Quieres ver un resumen básico o intentarlo de nuevo?')

      // Fallback: mostrar resultados básicos generados cliente-lado
      const basicResults = generateBasicResults(finalAnswers, context.lang)
      setResult(basicResults)
      onComplete?.(basicResults)
    } finally {
      setLoading(false)
    }
  }

  // Reiniciar test
  const resetTest = () => {
    setStep(0)
    setAnswers({})
    setResult(null)
    setError(null)
    setCurrentQuestion(null)
    setTotalSteps(5)
    loadQuestion()
  }

  // Exportar resultados (solo si hay consentimiento)
  const exportResults = async () => {
    if (!result || !hasConsent) {
      alert('Para exportar resultados, necesitas dar consentimiento para guardar tus datos. Esto es para proteger tu privacidad.')
      return
    }

    try {
      const pdfBlob = await invokeEdgeFunction('generate-assessment-pdf', {
        results: result,
        lang: context.lang,
        includeResources: true,
        anonymized: false
      })

      // Descargar PDF
      const url = URL.createObjectURL(pdfBlob)
      const a = document.createElement('a')
      a.href = url
      a.download = `mental-map-radar-${new Date().toISOString().split('T')[0]}.pdf`
      a.click()
      URL.revokeObjectURL(url)

    } catch (err) {
      console.error('Export failed:', err)
      alert('No pude generar el PDF. Pero puedes copiar manualmente tus resultados desde la pantalla.')
    }
  }

  // Renderizar opciones de respuesta con accesibilidad
  const renderOptions = (options: AnswerOption[]) => {
    return options.map((opt, index) => (
      <motion.button
        key={opt.value}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: index * 0.05 }}
        whileTap={{ scale: 0.98 }}
        whileHover={{ scale: 1.02, backgroundColor: 'var(--accent-soft)' }}
        onClick={() => handleAnswer(opt)}
        className={`option-btn neo-glass ${answers[step]?.value === opt.value ? 'selected' : ''}`}
        data-value={JSON.stringify(opt.value)}
        aria-pressed={answers[step]?.value === opt.value}
        disabled={loading}
      >
        <span className="option-label">{opt.label}</span>
        {opt.hint && (
          <span className="option-hint" aria-hidden="true">
            {accessibilityProfile?.simplifyContent ? opt.hintSimple || opt.hint : opt.hint}
          </span>
        )}
        {opt.emoji && <span className="option-emoji" aria-hidden="true">{opt.emoji}</span>}
      </motion.button>
    ))
  }

  // Renderizar pregunta actual con animaciones y accesibilidad
  const renderQuestion = () => {
    if (!currentQuestion) {
      return (
        <div className="question-loading neo-glass">
          <div className="loading-spinner" aria-label="Cargando pregunta"></div>
          <p className="sr-only">Cargando tu pregunta personalizada...</p>
        </div>
      )
    }

    return (
      <motion.div
        key={currentQuestion.id}
        initial={{ opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: -20 }}
        transition={{ duration: 0.3, ease: "easeInOut" }}
        className="question-card neo-glass"
        role="region"
        aria-labelledby={`question-${currentQuestion.id}`}
      >
        {/* Header de la pregunta con progreso */}
        <div className="question-header">
          <div className="progress-container">
            <div 
              className="progress-bar neon-cyan"
              style={{ width: `${((step + 1) / totalSteps) * 100}%` }}
              role="progressbar"
              aria-valuenow={step + 1}
              aria-valuemin={0}
              aria-valuemax={totalSteps}
            />
          </div>
          <span className="progress-text" aria-live="polite">
            Pregunta {step + 1} de {totalSteps}
          </span>
        </div>

        {/* Texto de la pregunta con soporte para contenido enriquecido */}
        <h3 id={`question-${currentQuestion.id}`} className="question-text">
          {currentQuestion.text}
          {currentQuestion.emoji && <span className="question-emoji" aria-hidden="true"> {currentQuestion.emoji}</span>}
        </h3>

        {/* Contexto adicional si está disponible */}
        {currentQuestion.context && (
          <p className="question-context" dangerouslySetInnerHTML={{ 
            __html: accessibilityProfile?.simplifyContent 
              ? currentQuestion.contextSimple || currentQuestion.context 
              : currentQuestion.context 
          }} />
        )}

        {/* Opciones de respuesta */}
        <div className="options-grid" role="radiogroup" aria-labelledby={`question-${currentQuestion.id}`}>
          {renderOptions(currentQuestion.options)}
        </div>

        {/* Nota de privacidad si es modo anónimo */}
        {currentQuestion.anonymousMode && (
          <p className="anonymous-notice" role="note">
            🔒 Modo anónimo: tus respuestas no se guardarán permanentemente. 
            <button 
              className="link-button" 
              onClick={() => requestConsent({ purpose: 'save-results' })}
              aria-label="Dar consentimiento para guardar resultados"
            >
              ¿Quieres guardar tus resultados para ver tu progreso?
            </button>
          </p>
        )}
      </motion.div>
    )
  }

  // Renderizar resultados con visualización accesible
  const renderResults = () => {
    if (!result) return null

    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.4, ease: "easeOut" }}
        className="results-card neo-glass"
        role="region"
        aria-labelledby="results-title"
      >
        <h3 id="results-title" className="results-title">
          ✨ {result.personalizedMessage}
        </h3>

        {/* Visualización de insights con gráficos accesibles */}
        <div className="insights-grid">
          {Object.entries(result.insights).map(([key, value]) => (
            <div key={key} className="insight-item">
              <span className="insight-label">
                {getInsightLabel(key, context.lang)}
              </span>
              <div className="insight-value">
                <span className={`insight-badge ${value}`}>
                  {getInsightValueText(value, context.lang)}
                </span>
                {/* Barra de progreso accesible */}
                <div 
                  className="insight-bar"
                  role="progressbar"
                  aria-valuenow={getInsightNumericValue(value)}
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-label={`${getInsightLabel(key, context.lang)}: ${getInsightValueText(value, context.lang)}`}
                >
                  <div 
                    className={`insight-fill ${value}`}
                    style={{ width: `${getInsightNumericValue(value)}%` }}
                  />
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Recomendaciones de recursos */}
        {result.recommendations.length > 0 && (
          <div className="recommendations-section">
            <h4>🎯 Recursos recomendados para ti</h4>
            <div className="recommendations-list">
              {result.recommendations.map(rec => (
                <div key={rec.id} className="recommendation-item neo-glass">
                  <div className="recommendation-header">
                    <span className="recommendation-title">{rec.title}</span>
                    <span className={`recommendation-type ${rec.type}`}>
                      {getResourceTypeLabel(rec.type, context.lang)}
                    </span>
                  </div>
                  <div className="recommendation-actions">
                    <button 
                      className="action-btn primary"
                      onClick={() => handleResourceAction(rec.action, rec)}
                      aria-label={`${rec.action.type}: ${rec.title}`}
                    >
                      {getActionLabel(rec.action.type, context.lang)}
                    </button>
                    {rec.action.type === 'call' && rec.phone && (
                      <a 
                        href={`tel:${rec.phone}`}
                        className="action-btn secondary"
                        aria-label={`Llamar a ${rec.title}`}
                      >
                        📞 Llamar
                      </a>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Acciones post-resultados */}
        <div className="results-actions">
          <button 
            className="action-btn primary neon-cyan"
            onClick={() => scrollToChatWithAgent('neuroDivergent', result.insights)}
            aria-label="Hablar con IA sobre tus resultados"
          >
            💬 Hablar con IA sobre esto
          </button>

          {hasConsent && (
            <button 
              className="action-btn secondary"
              onClick={exportResults}
              aria-label="Exportar resultados como PDF"
            >
              📄 Exportar resultados
            </button>
          )}

          <button 
            className="action-btn ghost"
            onClick={resetTest}
            aria-label="Hacer otro test"
          >
            🔄 Hacer otro test
          </button>
        </div>

        {/* Nota de privacidad y ética */}
        <p className="results-disclaimer" role="note">
          <strong>Importante:</strong> Este test no es un diagnóstico médico. 
          Es una herramienta de autoconocimiento basada en indicadores validados. 
          Si algo de tus resultados te preocupa, habla con un profesional de salud mental 
          LGBTQ+ affirming y neuro-affirming. Tus datos están protegidos: 
          {hasConsent ? ' guardados de forma segura y encriptada' : ' no se han guardado permanentemente'}.
        </p>
      </motion.div>
    )
  }

  // Manejar acciones de recursos
  const handleResourceAction = async (action: any, resource: any) => {
    switch (action.type) {
      case 'view':
        if (resource.url) {
          window.open(resource.url, '_blank', 'noopener,noreferrer')
        }
        break
      case 'chat':
        await scrollToChatWithAgent('educator', { resourceContext: resource })
        break
      case 'save':
        // Guardar recurso en preferencias del usuario (si hay consentimiento)
        if (hasConsent && userId) {
          await invokeEdgeFunction('save-user-resource', {
            userId,
            resourceId: resource.id,
            context: { savedFrom: 'radar-results' }
          })
          alert('Recurso guardado en tus favoritos. Lo encontrarás en tu perfil.')
        } else {
          // Fallback: copiar al portapapeles
          navigator.clipboard.writeText(resource.url || resource.title)
          alert('Enlace copiado al portapapeles. ¡Guárdalo donde puedas encontrarlo luego!')
        }
        break
    }
  }

  // Scroll suave al chat con contexto prellenado
  const scrollToChatWithAgent = async (agent: string, context: any) => {
    // Navegar a la sección de chat si no estamos allí
    if (window.location.hash !== '#chat') {
      window.location.hash = '#chat'
    }

    // Esperar un poco para que la navegación se complete
    await new Promise(resolve => setTimeout(resolve, 300))

    // Encontrar el input del chat y prellenar con contexto
    const chatInput = document.getElementById('chat-input') as HTMLInputElement
    if (chatInput) {
      const prefillMessage = generateChatPrefill(agent, context, result?.insights)
      chatInput.value = prefillMessage
      chatInput.focus()

      // Trigger de evento para que el componente de chat lo detecte
      chatInput.dispatchEvent(new Event('input', { bubbles: true }))
    }

    // Scroll suave al chat
    document.getElementById('chat-section')?.scrollIntoView({ 
      behavior: 'smooth', 
      block: 'start' 
    })
  }

  // Generar mensaje prellenado para el chat
  const generateChatPrefill = (agent: string, context: any, insights?: any): string => {
    const lang = context.lang || 'es'
    const prefillTemplates: Record<string, Record<string, string>> = {
      neuroDivergent: {
        es: `Hola, acabo de hacer el test Radar y mis resultados muestran ${Object.entries(insights || {}).filter(([_, v]) => v === 'high').map(([k]) => k).join(', ') || 'algunos patrones que me gustaría entender mejor'}. ¿Podemos hablar sobre estrategias para ${Object.keys(insights || {})[0] || 'regular emociones'}?`,
        en: `Hi, I just took the Radar test and my results show ${Object.entries(insights || {}).filter(([_, v]) => v === 'high').map(([k]) => k).join(', ') || 'some patterns I'd like to understand better'}. Can we talk about strategies for ${Object.keys(insights || {})[0] || 'emotional regulation'}?`
      },
      educator: {
        es: `Hola, mis resultados del test Radar sugieren que podría beneficiarme de recursos sobre ${context.resourceContext?.title || 'salud mental'}. ¿Puedes ayudarme a encontrar más información basada en evidencia?`,
        en: `Hi, my Radar test results suggest I could benefit from resources about ${context.resourceContext?.title || 'mental health'}. Can you help me find more evidence-based information?`
      }
    }

    return prefillTemplates[agent]?.[lang] || prefillTemplates.neuroDivergent.es
  }

  // Fallback question si falla la carga adaptativa
  const getFallbackQuestion = (stepIndex: number, lang: string): AdaptiveQuestion => {
    const fallbackQuestions: Record<string, AdaptiveQuestion> = {
      '0': {
        id: 'fallback-0',
        text: lang === 'es' ? '¿Con qué frecuencia te sientes abrumadx por estímulos (ruido, luz, gente)?' : 'How often do you feel overwhelmed by stimuli (noise, light, people)?',
        options: [
          { label: lang === 'es' ? 'Sí, a menudo' : 'Yes, often', value: 2, emoji: '🌪️' },
          { label: lang === 'es' ? 'A veces' : 'Sometimes', value: 1, emoji: '🌤️' },
          { label: lang === 'es' ? 'Raramente' : 'Rarely', value: 0, emoji: '☀️' }
        ],
        requiresConsent: false
      }
      // ... más preguntas fallback
    }

    return fallbackQuestions[stepIndex.toString()] || fallbackQuestions['0']
  }

  // Generar resultados básicos cliente-lado como fallback
  const generateBasicResults = (answers: Record<number, any>, lang: string): RadarResults => {
    const scores = Object.values(answers).reduce((acc, curr) => acc + (curr?.value || 0), 0)
    const maxScore = Object.keys(answers).length * 2
    const percentage = Math.round((scores / maxScore) * 100)

    const riskLevel = percentage >= 70 ? 'high' : percentage >= 40 ? 'moderate' : 'low'

    return {
      insights: {
        emotionalRegulation: riskLevel,
        sensorySensitivity: riskLevel,
        minorityStress: riskLevel,
        executiveFunction: riskLevel
      },
      recommendations: [
        {
          id: 'fallback-resource-1',
          title: lang === 'es' ? 'Guía de Grounding para Momentos Intensos' : 'Grounding Guide for Intense Moments',
          type: 'guide',
          relevance: 0.9,
          action: { type: 'view' }
        },
        {
          id: 'fallback-resource-2',
          title: lang === 'es' ? 'Líneas de Crisis LGBTQ+ Affirming' : 'LGBTQ+ Affirming Crisis Lines',
          type: 'hotline',
          relevance: 0.85,
          action: { type: 'call' }
        }
      ],
      riskLevel,
      personalizedMessage: lang === 'es' 
        ? 'Gracias por compartir. Tus respuestas sugieren que podrías beneficiarte de herramientas de regulación emocional. No es un diagnóstico, solo una guía para explorar.'
        : 'Thank you for sharing. Your responses suggest you could benefit from emotional regulation tools. This is not a diagnosis, just a guide to explore.'
    }
  }

  // Helpers para etiquetas y textos
  const getInsightLabel = (key: string, lang: string): string => {
    const labels: Record<string, Record<string, string>> = {
      emotionalRegulation: {
        es: 'Regulación emocional',
        en: 'Emotional regulation'
      },
      sensorySensitivity: {
        es: 'Sensibilidad sensorial',
        en: 'Sensory sensitivity'
      },
      minorityStress: {
        es: 'Estrés por minoría',
        en: 'Minority stress'
      },
      executiveFunction: {
        es: 'Función ejecutiva',
        en: 'Executive function'
      }
    }
    return labels[key]?.[lang] || labels[key]?.es || key
  }

  const getInsightValueText = (value: string, lang: string): string => {
    const texts: Record<string, Record<string, string>> = {
      low: { es: 'Bajo', en: 'Low' },
      moderate: { es: 'Moderado', en: 'Moderate' },
      high: { es: 'Alto', en: 'High' }
    }
    return texts[value]?.[lang] || texts[value]?.es || value
  }

  const getInsightNumericValue = (value: string): number => {
    const values: Record<string, number> = { low: 33, moderate: 66, high: 100 }
    return values[value] || 50
  }

  const getResourceTypeLabel = (type: string, lang: string): string => {
    const labels: Record<string, Record<string, string>> = {
      guide: { es: 'Guía', en: 'Guide' },
      center: { es: 'Centro', en: 'Center' },
      hotline: { es: 'Línea de ayuda', en: 'Hotline' },
      community: { es: 'Comunidad', en: 'Community' }
    }
    return labels[type]?.[lang] || labels[type]?.es || type
  }

  const getActionLabel = (action: string, lang: string): string => {
    const labels: Record<string, Record<string, string>> = {
      view: { es: 'Ver recurso', en: 'View resource' },
      call: { es: 'Llamar', en: 'Call' },
      chat: { es: 'Hablar con IA', en: 'Chat with AI' },
      save: { es: 'Guardar', en: 'Save' }
    }
    return labels[action]?.[lang] || labels[action]?.es || action
  }

  // Render principal con manejo de estados
  return (
    <div className="radar-container-v6" data-testid="radar-test-v6">
      {/* Banner de crisis siempre visible si hay riesgo */}
      {result?.riskLevel === 'high' || result?.riskLevel === 'crisis' ? (
        <CrisisBanner 
          severity={result.riskLevel}
          resources={result.recommendations.filter(r => r.type === 'hotline')}
          lang={context.lang}
          accessibility={accessibilityProfile}
        />
      ) : null}

      {/* Estado de carga global */}
      {loading && !currentQuestion && !result && (
        <div className="global-loading" role="status" aria-live="polite">
          <div className="loading-spinner-large"></div>
          <p>Preparando tu experiencia personalizada...</p>
        </div>
      )}

      {/* Estado de error */}
      {error && (
        <div className="error-banner neo-glass" role="alert">
          <p>{error}</p>
          <div className="error-actions">
            <button onClick={() => loadQuestion(answers[step - 1])} className="action-btn primary">
              🔄 Reintentar
            </button>
            <button onClick={() => setCurrentQuestion(getFallbackQuestion(step, context.lang))} className="action-btn secondary">
              ✨ Modo simplificado
            </button>
          </div>
        </div>
      )}

      {/* Contenido principal con animaciones */}
      <AnimatePresence mode="wait">
        {!result ? (
          // Modo pregunta
          <motion.div
            key="question-mode"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            {renderQuestion()}
          </motion.div>
        ) : (
          // Modo resultados
          <motion.div
            key="results-mode"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            {renderResults()}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Footer con información de privacidad */}
      <div className="radar-footer" role="contentinfo">
        <p className="privacy-note">
          🔒 <strong>Privacidad primero:</strong> {hasConsent 
            ? 'Tus datos están encriptados y solo tú puedes acceder a ellos.' 
            : 'Modo anónimo: nada se guarda permanentemente.'}
          <button 
            className="link-button" 
            onClick={() => {/* abrir modal de privacidad */}}
            aria-label="Ver política de privacidad completa"
          >
            Más información
          </button>
        </p>
      </div>
    </div>
  )
}

// Types para TypeScript (en archivo separado en producción)
interface AdaptiveQuestion {
  id: string
  text: string
  emoji?: string
  context?: string
  contextSimple?: string
  options: AnswerOption[]
  requiresConsent?: boolean
  anonymousMode?: boolean
}

interface AnswerOption {
  label: string
  value: any
  hint?: string
  hintSimple?: string
  emoji?: string
}

interface AccessibilityPreferences {
  simplifyContent?: boolean
  largeText?: boolean
  reducedMotion?: boolean
  highContrast?: boolean
  voiceNavigation?: boolean
}
