    identity?: { queer?: boolean }
    neurotype?: { detected?: boolean }
    accessibility?: AccessibilityPreferences
  }
}

interface RadarResults {
  insights: {
    emotionalRegulation: 'low' | 'moderate' | 'high'
    sensorySensitivity: 'low' | 'moderate' | 'high'
    minorityStress: 'low' | 'moderate' | 'high'
    executiveFunction: 'low' | 'moderate' | 'high'
  }
  recommendations: ResourceRecommendation[]
  riskLevel: 'low' | 'moderate' | 'high' | 'crisis'
  personalizedMessage: string
}

interface ResourceRecommendation {
  id: string
  title: string
  type: 'guide' | 'center' | 'hotline' | 'community'
  relevance: number
  action: { type: 'view' | 'call' | 'chat' | 'save' }
}

export default function InteractiveRadar6({ userId, sessionId, onComplete, context }: RadarTestProps) {
  const [step, setStep] = useState(0)
  const [answers, setAnswers] = useState<Record<number, any>>({})
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<RadarResults | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [currentQuestion, setCurrentQuestion] = useState<AdaptiveQuestion | null>(null)

  const { profile: accessibilityProfile } = useAccessibility()
  const { hasConsent, requestConsent } = useConsent()

  // Total de pasos dinámico según respuestas anteriores (adaptativo)
  const [totalSteps, setTotalSteps] = useState(5)

  // Cargar pregunta inicial o adaptativa
  const loadQuestion = useCallback(async (prevAnswer?: any) => {
    if (loading) return

    setLoading(true)
    setError(null)

    try {
      const { question, nextSteps } = await invokeEdgeFunction('radar-adaptive-engine-v6', {
        sessionId,
        userId,
        step,
        prevAnswer,
        context: {
          lang: context.lang,
          mood: context.mood,
          identity: context.identity,
          neurotype: context.neurotype,
          accessibility: accessibilityProfile
        },
        ethicalConstraints: {
          neverDiagnose: true,
          alwaysValidate: true,
          consentRequired: !hasConsent
        }
      })

      setCurrentQuestion(question)

      // Si el motor adaptativo cambia el número total de pasos, actualizar
      if (nextSteps && nextSteps !== totalSteps) {
        setTotalSteps(nextSteps)
      }

      // Solicitar consentimiento si es necesario y no se ha dado
      if (!hasConsent && question.requiresConsent) {
        const consentGiven = await requestConsent({
          purpose: 'personalize-test-results',
          duration: 'this-session-only',
          dataTypes: ['answers', 'mood-context'],
          sharing: 'never-share-with-third-parties'
        })

        if (!consentGiven) {
          // Si no da consentimiento, continuar con modo anónimo limitado
          setCurrentQuestion(prev => prev ? { ...prev, anonymousMode: true } : null)
        }
      }

    } catch (err) {
      console.error('Error loading question:', err)
      setError('No pude cargar la pregunta. ¿Quieres intentarlo de nuevo o usar el modo simplificado?')

      // Fallback a pregunta estática si falla la adaptativa
      setCurrentQuestion(getFallbackQuestion(step, context.lang))
    } finally {
      setLoading(false)
    }
  }, [step, sessionId, userId, context, accessibilityProfile, hasConsent, requestConsent, loading, totalSteps])

  // Efecto para cargar pregunta al montar o cambiar de paso
  useEffect(() => {
    if (step < totalSteps && !currentQuestion) {
      loadQuestion(answers[step - 1])
    }
  }, [step, totalSteps, currentQuestion, loadQuestion, answers])

  // Manejar respuesta del usuario
  const handleAnswer = async (answer: any) => {
    // Guardar respuesta localmente primero (para recuperación si falla la red)
    setAnswers(prev => ({ ...prev, [step]: answer }))

    // Feedback visual inmediato
    const optionElements = document.querySelectorAll('.option-btn')
    optionElements.forEach(btn => {
      if (btn.getAttribute('data-value') === JSON.stringify(answer.value)) {
        btn.classList.add('selected')
        // Haptic feedback en móvil si está disponible
        if ('vibrate' in navigator) {
          navigator.vibrate(50)
        }
      }
    })

    // Si es la última pregunta, calcular resultado final
    if (step === totalSteps - 1) {
      await finalizeTest({ ...answers, [step]: answer })
    } else {
      // Cargar siguiente pregunta adaptativa
      setStep(prev => prev + 1)
      // La pregunta se cargará automáticamente por el useEffect
    }
  }

  // Finalizar test y obtener resultados
  const finalizeTest = async (finalAnswers: Record<number, any>) => {
    setLoading(true)

    try {
      const { insights, recommendations, riskLevel, personalizedMessage } = await invokeEdgeFunction('radar-finalize-v6', {
        sessionId,
        userId,
        answers: finalAnswers,
        context: {
          lang: context.lang,
          mood: context.mood,
          identity: context.identity,
          neurotype: context.neurotype,
          accessibility: accessibilityProfile
        },
        consent: {
          saveResults: hasConsent,
          anonymized: !hasConsent,
          research: false // por defecto, se puede cambiar en preferencias
        }
      })

      const results: RadarResults = {
        insights,
        recommendations,
        riskLevel,
        personalizedMessage
      }

      setResult(results)

      // Callback para el componente padre
      onComplete?.(results)

      // Guardar resultados solo si hay consentimiento explícito
      if (hasConsent && userId) {
        await invokeEdgeFunction('save-assessment-v6', {
          userId,
          type: 'radar-v6',
          answers: finalAnswers,
          results,
          anonymized: false
        }).catch(err => console.warn('Failed to save results:', err))
      }

    } catch (err) {
      console.error('Error finalizing test:', err)
      setError('No pude procesar tus respuestas. Pero tus respuestas están guardadas localmente. ¿Quieres ver un resumen básico o intentarlo de nuevo?')

      // Fallback: mostrar resultados básicos generados cliente-lado
      const basicResults = generateBasicResults(finalAnswers, context.lang)
      setResult(basicResults)
      onComplete?.(basicResults)
    } finally {
      setLoading(false)
    }
  }

  // Reiniciar test
  const resetTest = () => {
    setStep(0)
    setAnswers({})
    setResult(null)
    setError(null)
    setCurrentQuestion(null)
    setTotalSteps(5)
    loadQuestion()
  }

  // Exportar resultados (solo si hay consentimiento)
  const exportResults = async () => {
    if (!result || !hasConsent) {
      alert('Para exportar resultados, necesitas dar consentimiento para guardar tus datos. Esto es para proteger tu privacidad.')
      return
    }

    try {
      const pdfBlob = await invokeEdgeFunction('generate-assessment-pdf', {
        results: result,
        lang: context.lang,
        includeResources: true,
        anonymized: false
      })

      // Descargar PDF
      const url = URL.createObjectURL(pdfBlob)
      const a = document.createElement('a')
      a.href = url
      a.download = `mental-map-radar-${new Date().toISOString().split('T')[0]}.pdf`
      a.click()
      URL.revokeObjectURL(url)

    } catch (err) {
      console.error('Export failed:', err)
      alert('No pude generar el PDF. Pero puedes copiar manualmente tus resultados desde la pantalla.')
    }
  }

  // Renderizar opciones de respuesta con accesibilidad
  const renderOptions = (options: AnswerOption[]) => {
    return options.map((opt, index) => (
      <motion.button
        key={opt.value}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: index * 0.05 }}
        whileTap={{ scale: 0.98 }}
        whileHover={{ scale: 1.02, backgroundColor: 'var(--accent-soft)' }}
        onClick={() => handleAnswer(opt)}
        className={`option-btn neo-glass ${answers[step]?.value === opt.value ? 'selected' : ''}`}
        data-value={JSON.stringify(opt.value)}
        aria-pressed={answers[step]?.value === opt.value}
        disabled={loading}
      >
        <span className="option-label">{opt.label}</span>
        {opt.hint && (
          <span className="option-hint" aria-hidden="true">
            {accessibilityProfile?.simplifyContent ? opt.hintSimple || opt.hint : opt.hint}
          </span>
        )}
        {opt.emoji && <span className="option-emoji" aria-hidden="true">{opt.emoji}</span>}
      </motion.button>
    ))
  }

  // Renderizar pregunta actual con animaciones y accesibilidad
  const renderQuestion = () => {
    if (!currentQuestion) {
      return (
        <div className="question-loading neo-glass">
          <div className="loading-spinner" aria-label="Cargando pregunta"></div>
          <p className="sr-only">Cargando tu pregunta personalizada...</p>
        </div>
      )
    }

    return (
      <motion.div
        key={currentQuestion.id}
        initial={{ opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: -20 }}
        transition={{ duration: 0.3, ease: "easeInOut" }}
        className="question-card neo-glass"
        role="region"
        aria-labelledby={`question-${currentQuestion.id}`}
      >
        {/* Header de la pregunta con progreso */}
        <div className="question-header">
          <div className="progress-container">
            <div 
              className="progress-bar neon-cyan"
              style={{ width: `${((step + 1) / totalSteps) * 100}%` }}
              role="progressbar"
              aria-valuenow={step + 1}
              aria-valuemin={0}
              aria-valuemax={totalSteps}
            />
          </div>
          <span className="progress-text" aria-live="polite">
            Pregunta {step + 1} de {totalSteps}
          </span>
        </div>

        {/* Texto de la pregunta con soporte para contenido enriquecido */}
        <h3 id={`question-${currentQuestion.id}`} className="question-text">
          {currentQuestion.text}
          {currentQuestion.emoji && <span className="question-emoji" aria-hidden="true"> {currentQuestion.emoji}</span>}
        </h3>

        {/* Contexto adicional si está disponible */}
        {currentQuestion.context && (
          <p className="question-context" dangerouslySetInnerHTML={{ 
            __html: accessibilityProfile?.simplifyContent 
              ? currentQuestion.contextSimple || currentQuestion.context 
              : currentQuestion.context 
          }} />
        )}

        {/* Opciones de respuesta */}
        <div className="options-grid" role="radiogroup" aria-labelledby={`question-${currentQuestion.id}`}>
          {renderOptions(currentQuestion.options)}
        </div>

        {/* Nota de privacidad si es modo anónimo */}
        {currentQuestion.anonymousMode && (
          <p className="anonymous-notice" role="note">
            🔒 Modo anónimo: tus respuestas no se guardarán permanentemente. 
            <button 
              className="link-button" 
              onClick={() => requestConsent({ purpose: 'save-results' })}
              aria-label="Dar consentimiento para guardar resultados"
            >
              ¿Quieres guardar tus resultados para ver tu progreso?
            </button>
          </p>
        )}
      </motion.div>
    )
  }

  // Renderizar resultados con visualización accesible
  const renderResults = () => {
    if (!result) return null

    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.4, ease: "easeOut" }}
        className="results-card neo-glass"
        role="region"
        aria-labelledby="results-title"
      >
        <h3 id="results-title" className="results-title">
          ✨ {result.personalizedMessage}
        </h3>

        {/* Visualización de insights con gráficos accesibles */}
        <div className="insights-grid">
          {Object.entries(result.insights).map(([key, value]) => (
            <div key={key} className="insight-item">
              <span className="insight-label">
