              </span>
              <div className="insight-value">
                <span className={`insight-badge ${value}`}>
                  {getInsightValueText(value, context.lang)}
                </span>
                {/* Barra de progreso accesible */}
                <div 
                  className="insight-bar"
                  role="progressbar"
                  aria-valuenow={getInsightNumericValue(value)}
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-label={`${getInsightLabel(key, context.lang)}: ${getInsightValueText(value, context.lang)}`}
                >
                  <div 
                    className={`insight-fill ${value}`}
                    style={{ width: `${getInsightNumericValue(value)}%` }}
                  />
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Recomendaciones de recursos */}
        {result.recommendations.length > 0 && (
          <div className="recommendations-section">
            <h4>🎯 Recursos recomendados para ti</h4>
            <div className="recommendations-list">
              {result.recommendations.map(rec => (
                <div key={rec.id} className="recommendation-item neo-glass">
                  <div className="recommendation-header">
