          Si algo de tus resultados te preocupa, habla con un profesional de salud mental 
          LGBTQ+ affirming y neuro-affirming. Tus datos están protegidos: 
          {hasConsent ? ' guardados de forma segura y encriptada' : ' no se han guardado permanentemente'}.
        </p>
      </motion.div>
    )
  }

  // Manejar acciones de recursos
  const handleResourceAction = async (action: any, resource: any) => {
    switch (action.type) {
      case 'view':
        if (resource.url) {
          window.open(resource.url, '_blank', 'noopener,noreferrer')
        }
        break
      case 'chat':
        await scrollToChatWithAgent('educator', { resourceContext: resource })
        break
      case 'save':
        // Guardar recurso en preferencias del usuario (si hay consentimiento)
        if (hasConsent && userId) {
          await invokeEdgeFunction('save-user-resource', {
            userId,
            resourceId: resource.id,
            context: { savedFrom: 'radar-results' }
          })
          alert('Recurso guardado en tus favoritos. Lo encontrarás en tu perfil.')
        } else {
          // Fallback: copiar al portapapeles
          navigator.clipboard.writeText(resource.url || resource.title)
          alert('Enlace copiado al portapapeles. ¡Guárdalo donde puedas encontrarlo luego!')
        }
        break
    }
  }

  // Scroll suave al chat con contexto prellenado
  const scrollToChatWithAgent = async (agent: string, context: any) => {
    // Navegar a la sección de chat si no estamos allí
    if (window.location.hash !== '#chat') {
      window.location.hash = '#chat'
    }

    // Esperar un poco para que la navegación se complete
    await new Promise(resolve => setTimeout(resolve, 300))

    // Encontrar el input del chat y prellenar con contexto
    const chatInput = document.getElementById('chat-input') as HTMLInputElement
    if (chatInput) {
      const prefillMessage = generateChatPrefill(agent, context, result?.insights)
      chatInput.value = prefillMessage
      chatInput.focus()

      // Trigger de evento para que el componente de chat lo detecte
      chatInput.dispatchEvent(new Event('input', { bubbles: true }))
    }

    // Scroll suave al chat
    document.getElementById('chat-section')?.scrollIntoView({ 
      behavior: 'smooth', 
      block: 'start' 
    })
  }

  // Generar mensaje prellenado para el chat
  const generateChatPrefill = (agent: string, context: any, insights?: any): string => {
    const lang = context.lang || 'es'
    const prefillTemplates: Record<string, Record<string, string>> = {
      neuroDivergent: {
        es: `Hola, acabo de hacer el test Radar y mis resultados muestran ${Object.entries(insights || {}).filter(([_, v]) => v === 'high').map(([k]) => k).join(', ') || 'algunos patrones que me gustaría entender mejor'}. ¿Podemos hablar sobre estrategias para ${Object.keys(insights || {})[0] || 'regular emociones'}?`,
        en: `Hi, I just took the Radar test and my results show ${Object.entries(insights || {}).filter(([_, v]) => v === 'high').map(([k]) => k).join(', ') || 'some patterns I'd like to understand better'}. Can we talk about strategies for ${Object.keys(insights || {})[0] || 'emotional regulation'}?`
      },
      educator: {
        es: `Hola, mis resultados del test Radar sugieren que podría beneficiarme de recursos sobre ${context.resourceContext?.title || 'salud mental'}. ¿Puedes ayudarme a encontrar más información basada en evidencia?`,
        en: `Hi, my Radar test results suggest I could benefit from resources about ${context.resourceContext?.title || 'mental health'}. Can you help me find more evidence-based information?`
      }
    }

    return prefillTemplates[agent]?.[lang] || prefillTemplates.neuroDivergent.es
  }

  // Fallback question si falla la carga adaptativa
  const getFallbackQuestion = (stepIndex: number, lang: string): AdaptiveQuestion => {
    const fallbackQuestions: Record<string, AdaptiveQuestion> = {
      '0': {
        id: 'fallback-0',
        text: lang === 'es' ? '¿Con qué frecuencia te sientes abrumadx por estímulos (ruido, luz, gente)?' : 'How often do you feel overwhelmed by stimuli (noise, light, people)?',
        options: [
          { label: lang === 'es' ? 'Sí, a menudo' : 'Yes, often', value: 2, emoji: '🌪️' },
          { label: lang === 'es' ? 'A veces' : 'Sometimes', value: 1, emoji: '🌤️' },
          { label: lang === 'es' ? 'Raramente' : 'Rarely', value: 0, emoji: '☀️' }
        ],
        requiresConsent: false
      }
      // ... más preguntas fallback
    }

    return fallbackQuestions[stepIndex.toString()] || fallbackQuestions['0']
  }

  // Generar resultados básicos cliente-lado como fallback
  const generateBasicResults = (answers: Record<number, any>, lang: string): RadarResults => {
    const scores = Object.values(answers).reduce((acc, curr) => acc + (curr?.value || 0), 0)
    const maxScore = Object.keys(answers).length * 2
    const percentage = Math.round((scores / maxScore) * 100)

    const riskLevel = percentage >= 70 ? 'high' : percentage >= 40 ? 'moderate' : 'low'

    return {
      insights: {
        emotionalRegulation: riskLevel,
        sensorySensitivity: riskLevel,
        minorityStress: riskLevel,
        executiveFunction: riskLevel
      },
      recommendations: [
        {
          id: 'fallback-resource-1',
          title: lang === 'es' ? 'Guía de Grounding para Momentos Intensos' : 'Grounding Guide for Intense Moments',
          type: 'guide',
          relevance: 0.9,
          action: { type: 'view' }
        },
        {
          id: 'fallback-resource-2',
          title: lang === 'es' ? 'Líneas de Crisis LGBTQ+ Affirming' : 'LGBTQ+ Affirming Crisis Lines',
          type: 'hotline',
          relevance: 0.85,
          action: { type: 'call' }
        }
      ],
      riskLevel,
      personalizedMessage: lang === 'es' 
        ? 'Gracias por compartir. Tus respuestas sugieren que podrías beneficiarte de herramientas de regulación emocional. No es un diagnóstico, solo una guía para explorar.'
        : 'Thank you for sharing. Your responses suggest you could benefit from emotional regulation tools. This is not a diagnosis, just a guide to explore.'
    }
  }

  // Helpers para etiquetas y textos
  const getInsightLabel = (key: string, lang: string): string => {
    const labels: Record<string, Record<string, string>> = {
      emotionalRegulation: {
        es: 'Regulación emocional',
        en: 'Emotional regulation'
      },
      sensorySensitivity: {
        es: 'Sensibilidad sensorial',
        en: 'Sensory sensitivity'
      },
      minorityStress: {
        es: 'Estrés por minoría',
        en: 'Minority stress'
      },
      executiveFunction: {
        es: 'Función ejecutiva',
        en: 'Executive function'
      }
    }
    return labels[key]?.[lang] || labels[key]?.es || key
  }

  const getInsightValueText = (value: string, lang: string): string => {
    const texts: Record<string, Record<string, string>> = {
      low: { es: 'Bajo', en: 'Low' },
      moderate: { es: 'Moderado', en: 'Moderate' },
      high: { es: 'Alto', en: 'High' }
    }
    return texts[value]?.[lang] || texts[value]?.es || value
  }

  const getInsightNumericValue = (value: string): number => {
    const values: Record<string, number> = { low: 33, moderate: 66, high: 100 }
    return values[value] || 50
  }

  const getResourceTypeLabel = (type: string, lang: string): string => {
    const labels: Record<string, Record<string, string>> = {
      guide: { es: 'Guía', en: 'Guide' },
      center: { es: 'Centro', en: 'Center' },
      hotline: { es: 'Línea de ayuda', en: 'Hotline' },
      community: { es: 'Comunidad', en: 'Community' }
    }
    return labels[type]?.[lang] || labels[type]?.es || type
  }

  const getActionLabel = (action: string, lang: string): string => {
    const labels: Record<string, Record<string, string>> = {
      view: { es: 'Ver recurso', en: 'View resource' },
      call: { es: 'Llamar', en: 'Call' },
      chat: { es: 'Hablar con IA', en: 'Chat with AI' },
      save: { es: 'Guardar', en: 'Save' }
    }
    return labels[action]?.[lang] || labels[action]?.es || action
  }

  // Render principal con manejo de estados
  return (
    <div className="radar-container-v6" data-testid="radar-test-v6">
      {/* Banner de crisis siempre visible si hay riesgo */}
      {result?.riskLevel === 'high' || result?.riskLevel === 'crisis' ? (
        <CrisisBanner 
          severity={result.riskLevel}
          resources={result.recommendations.filter(r => r.type === 'hotline')}
          lang={context.lang}
          accessibility={accessibilityProfile}
        />
      ) : null}

      {/* Estado de carga global */}
      {loading && !currentQuestion && !result && (
        <div className="global-loading" role="status" aria-live="polite">
          <div className="loading-spinner-large"></div>
          <p>Preparando tu experiencia personalizada...</p>
        </div>
      )}

      {/* Estado de error */}
      {error && (
        <div className="error-banner neo-glass" role="alert">
          <p>{error}</p>
          <div className="error-actions">
            <button onClick={() => loadQuestion(answers[step - 1])} className="action-btn primary">
              🔄 Reintentar
            </button>
            <button onClick={() => setCurrentQuestion(getFallbackQuestion(step, context.lang))} className="action-btn secondary">
              ✨ Modo simplificado
            </button>
          </div>
        </div>
      )}

      {/* Contenido principal con animaciones */}
      <AnimatePresence mode="wait">
        {!result ? (
          // Modo pregunta
          <motion.div
            key="question-mode"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            {renderQuestion()}
          </motion.div>
        ) : (
          // Modo resultados
          <motion.div
            key="results-mode"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            {renderResults()}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Footer con información de privacidad */}
      <div className="radar-footer" role="contentinfo">
        <p className="privacy-note">
          🔒 <strong>Privacidad primero:</strong> {hasConsent 
            ? 'Tus datos están encriptados y solo tú puedes acceder a ellos.' 
            : 'Modo anónimo: nada se guarda permanentemente.'}
          <button 
            className="link-button" 
            onClick={() => {/* abrir modal de privacidad */}}
            aria-label="Ver política de privacidad completa"
          >
            Más información
          </button>
        </p>
      </div>
    </div>
  )
}

// Types para TypeScript (en archivo separado en producción)
interface AdaptiveQuestion {
  id: string
  text: string
  emoji?: string
  context?: string
  contextSimple?: string
  options: AnswerOption[]
  requiresConsent?: boolean
  anonymousMode?: boolean
}

interface AnswerOption {
  label: string
  value: any
  hint?: string
  hintSimple?: string
  emoji?: string
}

interface AccessibilityPreferences {
  simplifyContent?: boolean
  largeText?: boolean
  reducedMotion?: boolean
  highContrast?: boolean
  voiceNavigation?: boolean
}
